add('l017-type-partition','任何级别的所有走势均可分解为趋势与盘整；趋势分为上涨和下跌。','0075:010',['走势','走势类型','趋势','盘整','上涨','下跌'],relations=[('走势','走势类型','composed_of'),('趋势','上涨','composed_of'),('趋势','下跌','composed_of')])
add('l017-principle-one','技术分析基本原理一：任何级别的任何走势类型终要完成，即走势终完美。','0075:011',['走势终完美','走势类型','级别'])
add('l017-completion-conversion','走势终完美包含两个方面：趋势与盘整最终都要在图形上完成，且某种走势类型完成后转化为其他类型。','0076:002',['走势终完美','走势类型','趋势','盘整'],conditions=['转化以原走势类型已经完成为前提'])
add('l017-present-dilemma','在走势的当下，趋势或盘整继续延续还是改变构成不能预先消除的两难。','0076:001',['走势类型','当下','走势延伸'],conditions=['讨论走势的当下延续与改变'])
add('l017-center-definition','走势中枢是某级别走势类型中，至少三个连续次级别走势类型所重叠的部分。',['0076:003','0082:005'],['走势中枢','次级别','走势类型'],conditions=['至少三个','连续','次级别走势类型','前三个次级别走势类型均已完成'],relations=[('走势中枢','次级别','requires'),('走势中枢','走势类型','composed_of')],note='先按17课定义抽取，再复读18课计算说明补齐前三个均完成的限制；已视觉核对PDF76页定义，未以读者转述充作证据。')
add('l017-minimum-level-center','在最后不能再分解的最低级别，中枢以至少三个该级别单位K线的重叠部分定义。','0076:003',['最低级别','走势中枢','K线'],conditions=['最低不可再分解级别','至少三个该级别单位K线'],exceptions=['一般中枢的连续次级别走势类型递归定义在此不适用'],note='复读并视觉核对PDF76页：这是17课给出的最低级别设定下定义，保留其原始课次语境，未推定其覆盖后续笔与线段规则。')
add('l017-minimum-level-setting','实际操作的最低不可分解级别可以设定为1分钟或5分钟，也可以设定为1秒线。','0076:003',['最低级别','级别','K线'],conditions=['17课给出的实际操作级别设定示例'],note='视觉核对PDF76页，原文为操作设定示例，未改写为级别与固定K线周期永远等同。')
add('l017-consolidation-definition','盘整是只包含一个走势中枢的完成走势类型。',['0076:005','0082:006'],['盘整','走势类型','走势中枢'],conditions=['某级别','完成的走势类型','只有一个该级别中枢'],relations=[('盘整','走势中枢','defines')])
add('l017-trend-definition','趋势是至少包含两个依次同向走势中枢的完成走势类型；方向向上为上涨，向下为下跌。',['0076:006','0082:007'],['趋势','走势中枢','上涨','下跌'],conditions=['某级别','完成的走势类型','至少两个','依次同向','中枢之间不存在重叠'],relations=[('趋势','走势中枢','defines')],note='独立复读17、18课及视觉核对PDF76页；保留“完成”“同向”和18课补充的绝不重叠要求，原“至少包含两个以上”按至少两个表达。')
add('l017-principle-two','技术分析基本原理二：任何级别任何完成的走势类型必然包含至少一个走势中枢。',['0077:000','0077:001'],['走势类型','走势中枢','走势终完美'],conditions=['完成的走势类型','走势可以不断延续','不存在交易品种被永远取消交易的情况'],note='二次复读跨页论证及视觉核对PDF77页；将作者在原理前明确说明的持续交易前提一并保存，“一个以上”保留为至少一个。')
add('l017-decomposition-one','走势分解定理一：任何级别的任何走势可以分解为同级别盘整、下跌、上涨三种走势类型的连接。','0077:003',['走势分解','同级别','盘整','下跌','上涨'],conditions=['同级别走势类型连接'],relations=[('走势分解','同级别','requires')])
add('l017-decomposition-two','走势分解定理二：任何级别的任何走势类型至少由三段次级别走势类型构成。','0077:004',['走势分解','走势类型','次级别'],conditions=['至少三段次级别走势类型'])
add('l017-first-buy-transition','下跌走势完成后只能转为上涨或盘整；把握下跌走势转化的关节点买入对应第一类买点。','0077:005',['第一类买点','下跌','走势终完美'],conditions=['下跌走势已经完成'],relations=[('第一类买点','下跌','qualifies')])
add('l017-second-buy-definition','第一类买点出现后第一次次级别回调所制造的低点对应第二类买点。','0077:005',['第二类买点','第一类买点','次级别'],conditions=['第一类买点之后','第一次次级别回调的低点'],relations=[('第二类买点','第一类买点','requires')])
add('l017-second-buy-up-leg','第一类买点后的上涨或盘整须至少包含三个次级别运动，因此在第一次次级别回调后至少还须有一个向上的次级别运动。','0077:005',['第二类买点','走势分解','次级别','上涨','盘整'],conditions=['第一类买点有效','其后上涨或盘整依走势分解要求完成'],note='二次复读论证，记录作者关于必有后续上行段的结构命题，不将其改写为无成本、无执行风险的投资保证。')
add('l017-second-point-law','买卖点定律一：任何级别的第二类买卖点由次级别相应走势的第一类买点构成。','0077:007',['第二类买卖点','第一类买点','次级别'],note='视觉核对PDF77页，原文明写“第一类买点”而非“第一类买卖点”；本条忠实保留原措辞，卖点对称表述待跨篇交叉核对。')
add('l017-trend-reversal-law','趋势转折定律：任何级别上涨的转折由某级别第一类卖点构成；下跌的转折由某级别第一类买点构成。',['0077:009','0077:010'],['趋势转折','第一类买点','第一类卖点','级别'],conditions=['某级别不必是次级别'],exceptions=['次级别可能表现为第二类买卖点','不同级别可能同步出现第一类买卖点'],relations=[('趋势转折','第一类买点','requires'),('趋势转折','第一类卖点','requires')])
add('l017-overlap-within-sublevels','中枢定义中的重叠是次级别走势之间的重叠，不能理解为次级别与高级别的重叠。','0080:008',['走势中枢','次级别','重叠'],note='二次回看p80-b007明确作者日期头和b005/006读者问题，核对b008为作者澄清，避免把读者误解纳入定义。')
add('l017-overlap-example','作者以A从8到18元、B从18到12元、C从12到24元说明三个走势段的价格区间重叠。','0081:011',['走势中枢','重叠','价格区间'],note='二次核对b010作者日期头，本条只记录示例的三段区间；作者在此以问句要求求交，未把计算答案伪装成原文直接陈述。')
add('l018-center-first-three','中枢区间以前三个连续且完成的次级别走势类型A、B、C的重叠为准；高低点为a1/a2、b1/b2、c1/c2时，边界为max(a2,b2,c2)和min(a1,b1,c1)。','0082:005',['走势中枢','价格区间','次级别'],conditions=['前三个连续次级别走势类型均完成'],note='二次逐字复读公式：18课用圆括号写区间，20课用方括号；本条只断言上下边界，不凭标点推导开闭端点规则。')
add('l018-completed-sublevel-observable','已经完成的次级别走势类型可以在次级别图上辨识，不必再看次级别以下级别图。','0082:005',['次级别','走势类型','完成'],conditions=['走势类型已经完成'],note='二次复读，特别保留“完成的”限定；未与20课关于在再次级别观察未完成次级别形成过程的答复混为一谈。')
add('l018-consolidation-can-extend','三个重叠的连续次级别走势类型形成后，盘整已具备随时完成的条件，但也可以继续围绕该中枢延伸。','0083:001',['盘整','走势延伸','走势终完美','走势中枢'],conditions=['三个重叠的连续次级别走势类型已经形成'],exceptions=['满足最小结构条件不等于当下已经结束'])
add('l018-trend-can-extend','两个依次同向中枢形成后，趋势已具备随时结束的条件，也可继续形成更多同向中枢而延伸。','0083:002',['趋势','走势延伸','走势终完美','走势中枢'],conditions=['已有两个依次同向中枢'],exceptions=['满足趋势最小结构条件不等于已经结束'])
add('l018-extension-essence','趋势延伸表现为同级别同向中枢不断产生；盘整延伸表现为不产生新的中枢。','0083:003',['趋势','盘整','走势延伸','走势中枢'],relations=[('走势延伸','走势中枢','qualifies')])
add('l018-center-theorem-one','中枢定理一：趋势中连接两个同级别中枢的必然是次级别或更低级别的走势类型。','0083:004',['走势中枢','中枢连接','次级别','趋势'],conditions=['趋势中','两个同级别中枢'],note='二次复读原文“次级别以下级别”；按含次级别表达。并未把连接走势强制写成次级别趋势。')
add('l018-center-maintenance-iff','中枢维持的充分必要条件是：任何离开该中枢的走势类型属于次级别或更低级别，并以次级别或更低级别走势类型返回。','0084:000',['走势中枢','中枢维持','次级别'],conditions=['讨论原中枢的维持','离开与返回均在次级别及以下'],exceptions=['离开或返回若是同级别走势类型，就意味着形成新中枢'])
add('l018-center-theorem-two','中枢定理二：盘整中无论离开还是返回中枢的走势类型，都必然是次级别或更低级别。','0084:001',['盘整','走势中枢','次级别','中枢维持'],conditions=['盘整中'])
add('l018-extrema-lowest-level','以1分钟为最低级别时，盘整离开和返回的连接处有两种情形：至少三根1分钟K线重叠震荡后回头，或无至少三根K线重叠的V型走势；相应极端K线的极端位置构成盘整高低点。','0084:002',['盘整','高低点','最低级别','K线'],conditions=['观察离开与返回走势的连接处','以1分钟为最低级别的示例'],note='独立复读分项及适用语境；这是18课最低级别解释，并未换成后续分型定义。')
add('l018-center-destruction-iff','中枢定理三：某级别中枢被破坏，当且仅当一个次级别走势离开该中枢后，其后的次级别回抽走势不再回到中枢内。','0084:004',['走势中枢','中枢破坏','次级别'],conditions=['离开为次级别走势','其后回抽亦为次级别走势','回抽不重新回到中枢内'],relations=[('中枢破坏','次级别','requires')])
add('l018-destruction-pairs','中枢定理三的两个次级别走势组合只有趋势加盘整、趋势加反趋势、盘整加反趋势三种。','0084:005',['中枢破坏','趋势','盘整','反趋势'],conditions=['中枢定理三的次级别离开与回抽组合'])
add('l018-strong-destruction','作者认为趋势加盘整是较有力的中枢破坏形式：次级别向上突破后以盘整整理回抽，其后上涨往往较有力，特别在底部区间突破时。','0084:005',['中枢破坏','趋势','盘整','上涨'],conditions=['次级别向上突破','以盘整整理回抽','尤其底部区间'],note='二次复读，保留“往往”的经验性强弱限定，未改写为必然上涨。')
